INSERT INTO lessons (module_id, title, description, duration, published_at, position, origin, video_source, youtube_id, video_updated_at, created_at, updated_at) SELECT m.module_id, 'CEST e NCM: qual a diferença e por que isso importa na nota fiscal', 'O NCM mostra o que você vende e o CEST indica os produtos sujeitos à substituição tributária. Vídeo do canal ClickNotas.', '2:18', '2025-07-16', 4, 'admin', 'youtube', 'fbEJ1H0U1ts', NOW(), NOW(), NOW() FROM modules m WHERE m.system_id = 'fiscal' AND m.name = 'Documentos fiscais' AND NOT EXISTS (SELECT 1 FROM (SELECT youtube_id FROM lessons) x WHERE x.youtube_id = 'fbEJ1H0U1ts');
