INSERT INTO lessons (module_id, title, description, duration, published_at, position, origin, video_source, youtube_id, video_updated_at, created_at, updated_at) SELECT m.module_id, 'Split payment: o imposto descontado antes de você receber', 'O que é o split payment da Reforma Tributária, em que o imposto é separado no momento do pagamento. Vídeo do canal Monetizando Negócios.', '7:14', '2026-02-16', 2, 'admin', 'youtube', 'O462wDERq4g', NOW(), NOW(), NOW() FROM modules m WHERE m.system_id = 'fiscal' AND m.name = 'Reforma tributária' AND NOT EXISTS (SELECT 1 FROM (SELECT youtube_id FROM lessons) x WHERE x.youtube_id = 'O462wDERq4g');
